svg.script:
//
    (function() {
      var root = document.querySelector('.a12p5-root');
      if (!root) return;

      var btn = document.getElementById('a12p5-toggle-btn');
      var head = document.getElementById('a12p5-fetal-head');

      function toggleState() {
        var current = root.getAttribute('data-state') || 'repouso';
        var next = (current === 'repouso') ? 'retropulsao' : 'repouso';
        root.setAttribute('data-state', next);

        if (head) {
          head.setAttribute('aria-valuenow', next === 'retropulsao' ? '1' : '0');
          head.setAttribute('aria-valuetext', next === 'retropulsao' ? 'Cóccix em Retropulsão (Saída ampliada +2 a 3 cm)' : 'Cóccix em Repouso (Diâmetro basal 9,5 cm)');
        }
      }

      if (btn) {
        btn.addEventListener('click', function(e) {
          e.preventDefault();
          toggleState();
        });
        btn.addEventListener('keydown', function(e) {
          if (e.key === ' ' || e.key === 'Enter') {
            e.preventDefault();
            toggleState();
          }
        });
      }

      if (head) {
        head.addEventListener('click', function(e) {
          e.preventDefault();
          toggleState();
        });
        head.addEventListener('keydown', function(e) {
          if (e.key === ' ' || e.key === 'Enter' || e.key === 'ArrowDown' || e.key === 'ArrowUp' || e.key === 'ArrowRight' || e.key === 'ArrowLeft') {
            e.preventDefault();
            toggleState();
          }
        });

        // Simple drag interaction support
        var isDragging = false;
        var startY = 0;

        head.addEventListener('pointerdown', function(e) {
          isDragging = true;
          startY = e.clientY;
          head.setPointerCapture(e.pointerId);
        });

        head.addEventListener('pointermove', function(e) {
          if (!isDragging) return;
          var dy = e.clientY - startY;
          if (dy > 20) {
            root.setAttribute('data-state', 'retropulsao');
          } else if (dy < -20) {
            root.setAttribute('data-state', 'repouso');
          }
        });

        head.addEventListener('pointerup', function(e) {
          if (isDragging) {
            isDragging = false;
            try { head.releasePointerCapture(e.pointerId); } catch(err){}
          }
        });
      }
    })();
  //
